INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenquellen > Andere Dateiformate
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können Datenquellen wie CSV-Dateien strukturiert und maschinenlesbar sein?', 2, '[{"text": "Ja", "correct": true, "because": "CSV ist ein strukturiertes, maschinenlesbares Format"}, {"text": "Nein", "correct": false, "because": "CSV ist standardisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das JSON-Format ausschließlich für hierarchische Datenstrukturen geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "JSON kann auch flache Strukturen speichern"}, {"text": "Ja", "correct": false, "because": "JSON ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen XML-Dateien immer eine feste Struktur haben, um als Datenquelle zu dienen?', 2, '[{"text": "Nein", "correct": true, "because": "XML ist flexibel, erfordert aber ein Schema für Validierung"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Bildformate wie PNG als Datenquellen für Metadaten dienen?', 2, '[{"text": "Ja", "correct": true, "because": "PNG kann Metadaten wie EXIF enthalten"}, {"text": "Nein", "correct": false, "because": "Metadaten sind enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Dateiformate wie PDF maschinenlesbar ohne zusätzliche Verarbeitung?', 2, '[{"text": "Nein", "correct": true, "because": "PDF erfordert oft Extraktion für Maschinenlesbarkeit"}, {"text": "Ja", "correct": false, "because": "Extraktion ist nötig"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Dateiformat ist am besten geeignet, um tabellarische Daten zu speichern?', 2, '[{"text": "CSV", "correct": true, "because": "CSV ist für tabellarische Daten optimiert"}, {"text": "JSON", "correct": false, "because": "Besser für Hierarchien"}, {"text": "XML", "correct": false, "because": "Komplexer für Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wird häufig für hierarchische Datenstrukturen verwendet?', 3, '[{"text": "JSON", "correct": true, "because": "JSON ist ideal für verschachtelte Daten"}, {"text": "CSV", "correct": false, "because": "Flache Struktur"}, {"text": "TXT", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dateiformat ermöglicht die Speicherung von Metadaten zusammen mit visuellen Inhalten?', 2, '[{"text": "JPEG", "correct": true, "because": "JPEG speichert Metadaten wie EXIF"}, {"text": "CSV", "correct": false, "because": "Nur tabellarische Daten"}, {"text": "JSON", "correct": false, "because": "Keine visuellen Inhalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format ist besonders geeignet für menschenlesbare und maschinenlesbare strukturierte Daten?', 2, '[{"text": "XML", "correct": true, "because": "XML ist lesbar und strukturiert"}, {"text": "BLOB", "correct": false, "because": "Binär, nicht lesbar"}, {"text": "PDF", "correct": false, "because": "Schwer maschinenlesbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dateiformat ist am wenigsten geeignet für die direkte Verarbeitung in Datenbanken?', 2, '[{"text": "PDF", "correct": true, "because": "PDF erfordert Extraktion"}, {"text": "CSV", "correct": false, "because": "Leicht importierbar"}, {"text": "JSON", "correct": false, "because": "Gut verarbeitbar"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Dateiformate sind maschinenlesbar?', 4, '[{"text": "CSV", "correct": true, "because": "Strukturiertes Tabellenformat"}, {"text": "JSON", "correct": true, "because": "Strukturierte Daten"}, {"text": "XML", "correct": true, "because": "Strukturiertes Markup"}, {"text": "PDF", "correct": false, "because": "Extraktion nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften charakterisieren das JSON-Format?', 3, '[{"text": "Hierarchische Struktur", "correct": true, "because": "Unterstützt Verschachtelung"}, {"text": "Leichtgewichtig", "correct": true, "because": "Kompaktes Format"}, {"text": "Maschinenlesbar", "correct": true, "because": "Standard für APIs"}, {"text": "Feste Länge", "correct": false, "because": "Variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dateiformate können Metadaten speichern?', 4, '[{"text": "JPEG", "correct": true, "because": "Enthält EXIF-Daten"}, {"text": "PNG", "correct": true, "because": "Metadaten möglich"}, {"text": "PDF", "correct": true, "because": "Metadaten wie Autor"}, {"text": "CSV", "correct": false, "because": "Keine Metadatenstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das CSV-Format?', 3, '[{"text": "Einfache Struktur", "correct": true, "because": "Tabellarisch und leicht lesbar"}, {"text": "Breite Unterstützung", "correct": true, "because": "In vielen Tools nutzbar"}, {"text": "Kompakte Größe", "correct": true, "because": "Effizient bei Tabellen"}, {"text": "Hierarchische Daten", "correct": false, "because": "Nicht geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dateiformate eignen sich für komplexe Datenstrukturen?', 3, '[{"text": "JSON", "correct": true, "because": "Unterstützt Verschachtelung"}, {"text": "XML", "correct": true, "because": "Flexibel und strukturiert"}, {"text": "YAML", "correct": true, "because": "Hierarchisch und lesbar"}, {"text": "TXT", "correct": false, "because": "Unstrukturiert"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) CSV-Dateien sind maschinenlesbar und strukturiert. b) Sie eignen sich für hierarchische Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Strukturiert ja, Hierarchie nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JSON unterstützt hierarchische Strukturen. b) Es ist ausschließlich für tabellarische Daten geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hierarchie ja, Tabellen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) XML ist menschen- und maschinenlesbar. b) Es erfordert immer eine feste Struktur.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lesbar ja, Struktur flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Bildformate wie PNG können Metadaten enthalten. b) PDF ist ohne Verarbeitung maschinenlesbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Metadaten ja, PDF nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) YAML ist für komplexe Datenstrukturen geeignet. b) TXT ist strukturiert und maschinenlesbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "YAML ja, TXT nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

